import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"آلية الوقاية من مفارقات الزمن وضبطها","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0089-时间悖论防控机制.md","filePath":"ar/0089-时间悖论防控机制.md"}'),h={name:"ar/0089-时间悖论防控机制.md"};function l(o,t,i,n,p,s){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="آلية-الوقاية-من-مفارقات-الزمن-وضبطها" tabindex="-1">آلية الوقاية من مفارقات الزمن وضبطها <a class="header-anchor" href="#آلية-الوقاية-من-مفارقات-الزمن-وضبطها" aria-label="Permalink to &quot;آلية الوقاية من مفارقات الزمن وضبطها&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>89</td></tr><tr><td>الوحدة</td><td>التفاعل عبر الأبعاد وقواعد الزمن</td></tr><tr><td>الكلمات المفتاحية</td><td>مفارقة الزمن، الوقاية من المفارقات وضبطها، إصلاح السببية، استقرار الخط الزمني، تصنيف المفارقات</td></tr></tbody></table><h2 id="أولاً-تعريف-مفارقة-الزمن-وأخطارها" tabindex="-1">أولاً: تعريف مفارقة الزمن وأخطارها <a class="header-anchor" href="#أولاً-تعريف-مفارقة-الزمن-وأخطارها" aria-label="Permalink to &quot;أولاً: تعريف مفارقة الزمن وأخطارها&quot;">​</a></h2><p>مفارقة الزمن هي الظاهرة التي يصبح فيها المنطق السببي متناقضاً مع نفسه أثناء عملية الارتداد الزمني بسبب سلوك تدخلي. مفارقة الزمن أخطر نتائج عمليات الارتداد الزمني؛ فبمجرد حدوثها وعدم إصلاحها في الوقت المناسب، قد تطلق انقسام الخط الزمني وانهيار السلسلة السببية وحتى اهتزاز قوانين على المستوى الكوني. لذلك، آلية الوقاية من مفارقات الزمن وضبطها هي المكوّن الأكثر جوهرية وأهمية في منظومة أمان الارتداد الزمني بأكملها.</p><p>جوهر مفارقة الزمن «فشل الإغلاق السببي». في تدفق الزمن الطبيعي، لكل حدث أسبابه ونتائجه، وتقدم السلسلة السببية بنية خطية متصلة. تُدخل عملية الارتداد الزمني في فترة الماضي متغيراً قادماً من المستقبل؛ فإذا غيّر سلوك هذا المتغير الشروط السببية التي أدت إلى وجوده ذاته، يتشكل «انقطاع الحلقة السببية المغلقة» — أي التناقض المنطقي القائل: إذا حدث أ، فلن يحدث أ. يتجلى هذا التناقض على مستوى القوانين كتصادم عنيف للطاقة السببية؛ وإذا تعذر على شبكة القوانين امتصاص الطاقة المتصادمة، تنفجر في شكل مفارقة زمنية.</p><p>تعتمد درجة خطورة مفارقة الزمن على حجمها وموقع حدوثها. المفارقات صغيرة الحجم (كتغيير اختيارات يومية لشخص عادي) قد تسبب تقلبات سببية موضعية فقط، تستطيع شبكة القوانين امتصاصها وإصلاحها ذاتياً؛ والمفارقات متوسطة الحجم (كتغيير مصير شخصية تاريخية مهمة) قد تسبب تفرع الخط الزمني، مكونة خطوطاً زمنية موازية؛ والمفارقات كبيرة الحجم (كتغيير مسار حدث تاريخي بمستوى حضاري) قد تطلق انهيار السلسلة السببية، مؤدية إلى انهيار بنية قوانين الخط الزمني بأكمله. هدف آلية الوقاية من مفارقات الزمن وضبطها في كون هنغ يوان القضاء على المفارقات في مهدها، وضمان ألا تطلق أي عملية ارتداد زمني مفارقة متوسطة الحجم أو أكبر.</p><h2 id="ثانياً-تصنيف-مفارقات-الزمن" tabindex="-1">ثانياً: تصنيف مفارقات الزمن <a class="header-anchor" href="#ثانياً-تصنيف-مفارقات-الزمن" aria-label="Permalink to &quot;ثانياً: تصنيف مفارقات الزمن&quot;">​</a></h2><p>تبعاً لآلية تكوين المفارقات وشكل تجليها، تنقسم مفارقات الزمن إلى الفئات الأربع الكبرى التالية:</p><table tabindex="0"><thead><tr><th>نوع المفارقة</th><th>آلية التكوين</th><th>الحالة النموذجية</th><th>مستوى الخطر</th></tr></thead><tbody><tr><td>مفارقة قتل الجد</td><td>يؤدي سلوك المرتد إلى إزالة الشروط السببية لوجوده ذاته</td><td>يقتل المرتد في الماضي جده الخاص، فيؤدي ذلك إلى عدم ولادته أبداً</td><td>مرتفع جداً (أحمر)</td></tr><tr><td>المفارقة المعلوماتية</td><td>تُنقل معلومة من المستقبل إلى الماضي، فيستقبلها أهل الماضي ويطورونها، وتصبح في النهاية مصدر المعلومة المستقبلية، مكونة دورة معلوماتية بلا مصدر</td><td>عالم من المستقبل يرسل نظرية إلى الماضي، فينشر عالم من الماضي النظرية، والعالم المستقبلي تعلم هذه النظرية تحديداً من الوثائق التاريخية</td><td>مرتفع (برتقالي)</td></tr><tr><td>المفارقة الوجودية</td><td>يلتقي المرتد في الماضي بنفسه الماضية، فيتفاعل وجودان للذات الواحدة، محدثين اضطراباً سببياً في وعي الذات</td><td>يلتقي المرتد في الماضي بنسخته الأصغر ويتحدث معها، فيغير اختيارات حياتها، مما يغير بدوره ذكريات المرتد وشخصيته</td><td>مرتفع (برتقالي)</td></tr><tr><td>مفارقة الأحداث</td><td>يغير سلوك المرتد نتيجة حدث تاريخي مفصلي، مما يقتضي إعادة بناء السلسلة السببية لكل التاريخ اللاحق</td><td>يمنع المرتد في الماضي اندلاع حرب مفصلي، فيتغير التاريخ الكامل لمئات السنين اللاحقة تماماً</td><td>مرتفع جداً (أحمر)</td></tr></tbody></table><p>إلى جانب الفئات الأربع الكبرى المذكورة، توجد أيضاً مفارقات مركبة — مفارقات معقدة تجمع في آن واحد خصائص أكثر من نوعين من المفارقات. الوقاية من المفارقات المركبة وضبطها وإصلاحها أصعب بكثير من المفارقات أحادية النوع، وتتطلب استجابة طارئة من أعلى مستوى.</p><h2 id="ثالثاً-آلية-الوقاية-والضبط-المسبقين" tabindex="-1">ثالثاً: آلية الوقاية والضبط المسبقين <a class="header-anchor" href="#ثالثاً-آلية-الوقاية-والضبط-المسبقين" aria-label="Permalink to &quot;ثالثاً: آلية الوقاية والضبط المسبقين&quot;">​</a></h2><p>الاستراتيجية الأولى للوقاية من مفارقات الزمن وضبطها «الوقاية المسبقة» — أي إزالة احتمال توليد المفارقات بالوسائل المؤسسية والتقنية قبل بدء عملية الارتداد الزمني. تشمل آلية الوقاية والضبط المسبقين الحلقات الجوهرية التالية:</p><h3 id="_3-1-التقييم-السببي-قبل-الارتداد" tabindex="-1">3.1 التقييم السببي قبل الارتداد <a class="header-anchor" href="#_3-1-التقييم-السببي-قبل-الارتداد" aria-label="Permalink to &quot;3.1 التقييم السببي قبل الارتداد&quot;">​</a></h3><p>قبل الموافقة على أي عملية ارتداد زمني، يجب على فريق «محللي السببية» المحترف إجراء تقييم سببي قبل الارتداد. يشمل محتوى التقييم: كثافة السلسلة السببية للفترة الزمنية المستهدفة، وموقع العقد التاريخية المفصلية وحساسيتها، ودرجة الارتباط السببي بين المرتد نفسه والفترة الزمنية المستهدفة، ونطاق الانحراف السببي الذي قد يسببه سلوك التدخل المقترح. تُعبر نتائج التقييم بـ«مؤشر خطر المفارقة»؛ تُرفض طلبات الارتداد التي يزيد مؤشرها على 0.1، ولا تُوافق الطلبات التي يتراوح مؤشرها بين 0.01 و0.1 إلا بعد إضافة تدابير وقاية وضبط إضافية.</p><h3 id="_3-2-العزل-السببي-للمرتد" tabindex="-1">3.2 العزل السببي للمرتد <a class="header-anchor" href="#_3-2-العزل-السببي-للمرتد" aria-label="Permalink to &quot;3.2 العزل السببي للمرتد&quot;">​</a></h3><p>لمنع حدوث مفارقة قتل الجد والمفارقة الوجودية، يجب أن يخضع المرتد قبل دخول الفترة الزمنية المستهدفة لـ«معالجة العزل السببي». جوهر العزل السببي، عبر عمليات قوانين المرساة، «نزع» بصمة المرتد السببية مؤقتاً من السلسلة السببية للبُعد الخاص، بحيث لا يكون لوجود المرتد في الفترة الزمنية المستهدفة ارتباط مباشر بخطه السببي الماضي. بعد العزل السببي، حتى لو التقى المرتد في الماضي بجده أو بنسخته الماضية، لن يطلق مباشرة مفارقة قتل الجد أو المفارقة الوجودية — لأن وجود المرتد أصبح مؤقتاً مستقلاً عن السلسلة السببية الأصلية.</p><p>تطابق مدة صلاحية العزل السببي مدة الارتداد؛ بعد انتهاء الارتداد، تُعاد بصمة المرتد السببية إلى السلسلة السببية الأصلية. عند إعادة الربط، يُشترط «التحقق من استمرارية السببية»، لضمان التحام تجارب فترة الارتداد مع ذكريات المرتد الأصلية التحاماً سلساً.</p><h3 id="_3-3-نظام-القائمة-البيضاء-لسلوكيات-التدخل" tabindex="-1">3.3 نظام القائمة البيضاء لسلوكيات التدخل <a class="header-anchor" href="#_3-3-نظام-القائمة-البيضاء-لسلوكيات-التدخل" aria-label="Permalink to &quot;3.3 نظام القائمة البيضاء لسلوكيات التدخل&quot;">​</a></h3><p>تطبق سلوكيات التدخل في الارتداد الزمني «نظام قائمة بيضاء» صارماً — يُسمح بتنفيذ سلوكيات التدخل المقرّة مسبقاً والمدرجة في القائمة البيضاء فقط، ويُحظر صرامة أي سلوك تدخل خارج القائمة البيضاء. تُبنى القائمة البيضاء على أساس نتائج التقييم السببي قبل الارتداد، ولا تتضمن إلا سلوكيات التدخل ذات الانحراف السببي الضئيل للغاية وخطر المفارقة المنخفض للغاية.</p><p>أمثلة نموذجية لسلوكيات التدخل المدرجة في القائمة البيضاء: وضع معلومة في زاوية لا يلحظها أحد، وإجراء تبادل وجيز مع شخص غير مفصلي دون التأثير في مسار حياته، وإجراء تعديل زمني بالغ الدقة (لا يتجاوز بضع ثوانٍ) لحدث على وشك الحدوث طبيعياً. لا يجوز بأي حال إدراج أي سلوك تدخل قد يغير مصير الشخصيات المفصلية أو نتائج الأحداث المفصلية أو اتجاه تطور الحضارة في القائمة البيضاء.</p><h2 id="رابعاً-الرصد-أثناء-العملية-والاستجابة-الطارئة" tabindex="-1">رابعاً: الرصد أثناء العملية والاستجابة الطارئة <a class="header-anchor" href="#رابعاً-الرصد-أثناء-العملية-والاستجابة-الطارئة" aria-label="Permalink to &quot;رابعاً: الرصد أثناء العملية والاستجابة الطارئة&quot;">​</a></h2><p>حتى مع الوقاية المسبقة الصارمة، قد تنشأ أثناء عملية الارتداد ظروف غير متوقعة ترفع خطر المفارقة. لذلك، الرصد أثناء العملية والاستجابة الطارئة هما خط الدفاع الثاني لآلية الوقاية والضبط.</p><h3 id="_4-1-الرصد-السببي-اللحظي" tabindex="-1">4.1 الرصد السببي اللحظي <a class="header-anchor" href="#_4-1-الرصد-السببي-اللحظي" aria-label="Permalink to &quot;4.1 الرصد السببي اللحظي&quot;">​</a></h3><p>أثناء عملية الارتداد، تجري شبكة المرساة رصداً لحظياً لحالة السلسلة السببية في الفترة الزمنية المستهدفة. تشمل مؤشرات الرصد: معدل تغير كثافة السلسلة السببية، واستقرار العقد المفصلية، وإشارات مقدمات المفارقة (تقلبات شاذة في الطاقة السببية). تُحدَّث بيانات الرصد كل ملي ثانية، ويحللها «ذكاء اصطناعي لرصد السببية» تلقائياً؛ وأي شذوذ يُكتشف يطلق إنذاراً فوراً.</p><h3 id="_4-2-الاستجابة-الطارئة-بثلاثة-مستويات" tabindex="-1">4.2 الاستجابة الطارئة بثلاثة مستويات <a class="header-anchor" href="#_4-2-الاستجابة-الطارئة-بثلاثة-مستويات" aria-label="Permalink to &quot;4.2 الاستجابة الطارئة بثلاثة مستويات&quot;">​</a></h3><p>تبعاً لشدة خطر المفارقة، تنقسم الاستجابة الطارئة إلى ثلاثة مستويات:</p><ul><li><p><strong>استجابة المستوى الثالث (مستوى الإنذار المبكر)</strong>: يرصد النظام شذوذاً طفيفاً في السلسلة السببية، ويرتفع مؤشر خطر المفارقة فوق 0.01 دون بلوغ 0.05. إجراءات الاستجابة: تعليق سلوك التدخل الجاري، وعودة المرتد إلى حالة الملاحظة الخالصة، وتحليل الشذوذ وتقييمه من فريق محللي السببية؛ ولا تُستأنف العملية إلا بعد تأكيد السلامة.</p></li><li><p><strong>استجابة المستوى الثاني (مستوى التحذير)</strong>: يزداد شذوذ السلسلة السببية، ويرتفع مؤشر خطر المفارقة فوق 0.05 دون بلوغ 0.1، أو تظهر إشارات مقدمات مفارقة واضحة. إجراءات الاستجابة: إنهاء جميع سلوكيات التدخل فوراً، وتشغيل إجراء الانسحاب الطارئ للمرتد، وتكليف شبكة المرساة في الوقت نفسه بإجراء «تجميد السببية» على السلسلة السببية للفترة الزمنية المستهدفة — قفل حالة السلسلة السببية مؤقتاً لمنع مزيد من انتشار الشذوذ.</p></li><li><p><strong>استجابة المستوى الأول (مستوى الأزمة)</strong>: وقعت مفارقة فعلياً، أو تجاوز مؤشر خطر المفارقة 0.1. إجراءات الاستجابة: تشغيل الاستجابة الطارئة من أعلى مستوى فوراً، بقيادة مباشرة من لجنة قوانين الزمن، وتوظيف كل طاقة المرساة المتاحة لإجراء عمليات «إصلاح السببية»، مع التحضير في الوقت نفسه لتشغيل إجراء «عزل الخط الزمني» — عزل مقطع الخط الزمني المتأثر بالمفارقة عن الخط الزمني الرئيسي لتكوين حلقة زمنية مغلقة مستقلة، ومنع انتشار تأثير المفارقة إلى أجزاء أخرى من الخط الزمني الرئيسي.</p></li></ul><h2 id="خامساً-الإصلاح-السببي-اللاحق-والتدقيق" tabindex="-1">خامساً: الإصلاح السببي اللاحق والتدقيق <a class="header-anchor" href="#خامساً-الإصلاح-السببي-اللاحق-والتدقيق" aria-label="Permalink to &quot;خامساً: الإصلاح السببي اللاحق والتدقيق&quot;">​</a></h2><p>إذا وقعت مفارقة بالفعل، فإن الإصلاح السببي اللاحق هو آخر وسيلة إنقاذ. الطريقة الجوهرية للإصلاح السببي «طريقة حقن الطاقة السببية» — حقن طاقة تعويضية محسوبة بدقة عبر شبكة المرساة في السلسلة السببية المتضررة، لمعادلة التصادم السببي الذي أحدثته المفارقة، وإعادة السلسلة السببية إلى الاستقرار. تتطلب عملية الإصلاح دقة متناهية؛ ولا يجوز أن يتجاوز انحراف الطاقة المحقونة 10 أس سالب 6 من الطاقة المستهدفة، وإلا فقد تُطلق مفارقة ثانوية.</p><p>أما المفارقات التي أدت بالفعل إلى تفرع الخط الزمني، فطريقة إصلاحها «دمج الخطوط الزمنية» — إعادة دمج الخط الزمني المتفرع في الخط الزمني الرئيسي عبر عمليات المرساة. أثناء الدمج، يجب «الكتابة الفوقية السببية» على الأحداث المختلفة في الخط المتفرع، أي أن الأحداث الأصلية للخط الزمني الرئيسي تكتب فوق أحداث التفرع، ويُحتفظ في النهاية بخط زمني موحد واحد فقط.</p><p>بعد انتهاء جميع عمليات الارتداد الزمني، يجب قبول «تدقيق لاحق للعمليات الزمنية». يتولى التدقيق لجنة تدقيق قوانين الزمن، ويشمل محتواه: هل نُفذت عملية الارتداد بدقة وفق المخطط المقر، وهل وقعت سلوكيات تدخل خارج القائمة البيضاء، وهل بيانات الرصد السببي مكتملة، وهل ظهر خطر مفارقة وهل عولج معالجة سليمة. تُحفظ تقارير التدقيق أرشفة دائمة، بوصفها مرجعاً مهماً للموافقات اللاحقة على الارتداد.</p><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>آلية الوقاية من مفارقات الزمن وضبطها هي أكثر مشاريع الأمان دقة وتعقيداً في كون هنغ يوان في مجال قوانين الزمن. بالوقاية المسبقة أساساً، والرصد أثناء العملية درعاً، والإصلاح اللاحق خطاً دفاعياً أخيراً، تبني منظومة وقاية وضبط كاملة السلسلة قوامها «الوقاية — الرصد — الاستجابة — الإصلاح — التدقيق». وجود هذه الآلية يجعل الارتداد الزمني — تلك القدرة القانونية القوية والخطيرة — قابلاً للاستخدام الآمن في علم الآثار والبحث، دون أن يتحول إلى صندوق باندورا يهدم النظام السببي للكون.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>82-时间回溯基本原则 (المبادئ الأساسية للارتداد الزمني)</li><li>83-先观测后有限干涉准则 (معايير الملاحظة أولاً ثم التدخل المحدود)</li><li>27-锚点校准与维护 (معايرة المراسي وصيانتها)</li></ul>',35)])])}const b=a(h,[["render",l]]);export{c as __pageData,b as default};
